/**
 * One meaningful moment in the reading history.
 */

public enum ActivityKind: Equatable, Hashable {
    
    case added
    case started
    /**
     * Pages read in one sitting. Updates within an hour of each other are
     * merged into one entry.
     */
    case progress(fromPage: UInt32, toPage: UInt32
    )
    case finished
    /**
     * Moved back to Want to Read or Reading from another status.
     */
    case statusChanged(status: ReadingStatus
    )





}

#if compiler(>=6)
extension ActivityKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeActivityKind: FfiConverterRustBuffer {
    typealias SwiftType = ActivityKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ActivityKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .added
        
        case 2: return .started
        
        case 3: return .progress(fromPage: try FfiConverterUInt32.read(from: &buf), toPage: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .finished
        
        case 5: return .statusChanged(status: try FfiConverterTypeReadingStatus.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ActivityKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .added:
            writeInt(&buf, Int32(1))
        
        
        case .started:
            writeInt(&buf, Int32(2))
        
        
        case let .progress(fromPage,toPage):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(fromPage, into: &buf)
            FfiConverterUInt32.write(toPage, into: &buf)
            
        
        case .finished:
            writeInt(&buf, Int32(4))
        
        
        case let .statusChanged(status):
            writeInt(&buf, Int32(5))
            FfiConverterTypeReadingStatus.write(status, into: &buf)
            
        }
    }
}


