/**
 * Every error the API returns. `reason` fields are diagnostics for logs and
 * detail text; the host writes its own headline per case. (Fields avoid the
 * name `message`, which clashes with Kotlin's `Throwable.message`.)
 */
public 
enum LibraryError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The form or request is not acceptable; `reason` says which field.
     */
    case InvalidInput(reason: String
    )
    /**
     * The book form was refused: each entry names a `BookInput` field and
     * says what to fix, so the form shows it under that field.
     */
    case InvalidFields(fields: [FieldError]
    )
    case NotFound(id: UInt64
    )
    /**
     * That book is already in the library (importing the same catalogue
     * work or EPUB twice).
     */
    case AlreadyInLibrary(id: UInt64
    )
    /**
     * The library file could not be read or written. Nothing in memory
     * changed; the file on disk is left as it was.
     */
    case Storage(reason: String
    )
    /**
     * The library on disk was written by a newer version of the app.
     */
    case NewerLibrary(found: UInt32, supported: UInt32
    )
    /**
     * The online catalogue is switched off in Settings.
     */
    case CatalogueDisabled
    /**
     * No connection, DNS failure, or connection refused.
     */
    case Offline(reason: String
    )
    case Timeout
    /**
     * The catalogue answered, but not usefully (5xx, 429, maintenance).
     */
    case CatalogueUnavailable(reason: String
    )
    /**
     * The catalogue's answer could not be understood.
     */
    case BadResponse(reason: String
    )
    /**
     * The server's TLS certificate was rejected.
     */
    case Certificate(reason: String
    )
    /**
     * Any other network failure.
     */
    case Network(reason: String
    )
    /**
     * The file is not an EPUB this app can read.
     */
    case UnsupportedFile(reason: String
    )
    /**
     * The book has no saved EPUB to read (typed in, from the catalogue, or
     * imported before Pocket Library kept EPUBs), or the saved one is gone.
     */
    case NotReadable(reason: String
    )
    /**
     * The request was stopped with its `Cancellation`. Nothing changed.
     */
    case Cancelled
    /**
     * `shutdown()` was called; the instance accepts no more work.
     */
    case ShutDown

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension LibraryError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLibraryError: FfiConverterRustBuffer {
    typealias SwiftType = LibraryError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LibraryError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidFields(
            fields: try FfiConverterSequenceTypeFieldError.read(from: &buf)
            )
        case 3: return .NotFound(
            id: try FfiConverterUInt64.read(from: &buf)
            )
        case 4: return .AlreadyInLibrary(
            id: try FfiConverterUInt64.read(from: &buf)
            )
        case 5: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .NewerLibrary(
            found: try FfiConverterUInt32.read(from: &buf), 
            supported: try FfiConverterUInt32.read(from: &buf)
            )
        case 7: return .CatalogueDisabled
        case 8: return .Offline(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Timeout
        case 10: return .CatalogueUnavailable(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .BadResponse(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Certificate(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 14: return .UnsupportedFile(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 15: return .NotReadable(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 16: return .Cancelled
        case 17: return .ShutDown

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LibraryError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidFields(fields):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceTypeFieldError.write(fields, into: &buf)
            
        
        case let .NotFound(id):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(id, into: &buf)
            
        
        case let .AlreadyInLibrary(id):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(id, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NewerLibrary(found,supported):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(found, into: &buf)
            FfiConverterUInt32.write(supported, into: &buf)
            
        
        case .CatalogueDisabled:
            writeInt(&buf, Int32(7))
        
        
        case let .Offline(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Timeout:
            writeInt(&buf, Int32(9))
        
        
        case let .CatalogueUnavailable(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .BadResponse(reason):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Certificate(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Network(reason):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .UnsupportedFile(reason):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotReadable(reason):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(16))
        
        
        case .ShutDown:
            writeInt(&buf, Int32(17))
        
        }
    }
}


